String base = 'Trail cabin trail';
System.assert(base.contains('cabin'));
System.assert(base.endsWith('trail'));
System.assert('Cabin'.equalsIgnoreCase('cabin'));
System.assertEquals(6, base.indexOf('cabin'));
System.assertEquals(12, base.indexOf('trail', 7));
System.assertEquals(1, 'abc'.indexOfChar(98));
System.assertEquals(3, 'abca'.indexOfChar(97, 1));
System.assertEquals(6, base.indexOfIgnoreCase('CABIN'));
System.assertEquals(12, base.indexOfIgnoreCase('TRAIL', 7));
System.assert(String.isBlank('   '));
System.assert(String.isEmpty(''));
System.assert(!String.isNotBlank('   '));
System.assert(String.isNotEmpty('x'));
List<String> pieces = new List<String>{'one','two','three'};
System.assertEquals('one/two/three', String.join(pieces, '/'));
System.assertEquals('one two', String.format('{0} {1}', new List<Object>{'one', 'two'}));
System.assertEquals('spr', String.getCommonPrefix(new List<String>{'spruce', 'spring', 'sprout'}));
String gumbo = 'gumbo';
System.assertEquals(2, gumbo.getLevenshteinDistance('gambol'));
System.assertEquals(-1, gumbo.getLevenshteinDistance('gambol', 1));
System.assertEquals('ABC', String.fromCharArray(new List<Integer>{65, 66, 67}));
System.assertEquals('don\\\'t', String.escapeSingleQuotes('don\'t'));

